CREATE Proc [dbo].[uspInsertPayment] @OrderKey as int, @z_number as nvarchar(50), @order_type as nvarchar(50), @cash_sale as float, @credit_sale as float, @sub_total as float, @discount as float, @tax as float, @net_sale as float, @net_bill as float, @TiltId as int, @CounterId as int, @Service as float, @Tip as float as DECLARE @intErrorCode INT Declare @date datetime; Declare @OPId  int; Declare @Ordernumber int; declare @CurrDiscount as float; declare @DiscountPercent as nvarchar(10); declare @TableNo as nvarchar; declare @OrderNO as int; declare @AccStatus as int; set @AccStatus=0;    BEGIN TRANSACTION     select @date= order_date from Dine_In_Order where order_key = @OrderKey  Insert into Order_Payment(order_key,date,z_number,order_type,cash_sale,credit_sale,sub_total,discount,tax,net_sale,net_bill,ent,Tiltid,CounterId,ServiceCharges,Tip) values (@OrderKey,@date,@z_number,@order_type,@cash_sale,@credit_sale,@sub_total,@discount,@tax,@net_sale,@net_bill,'0',@TiltId,@CounterId,@Service,@Tip)      SELECT @intErrorCode = @@ERROR     IF (@intErrorCode <> 0) GOTO PROBLEM  update Dine_In_Order set service_status = 'Close',account_status = 'Paid',CounterId = @CounterId where order_key = @OrderKey and Tiltid=@TiltId SELECT @intErrorCode = @@ERROR     IF (@intErrorCode <> 0) GOTO PROBLEM  select @TableNo =  table_no from Dine_In_Order where order_key = @OrderKey and Tiltid=@TiltId update Tables set table_status = 'Close'where tables =@TableNo  set @AccStatus=1;  select @Ordernumber= order_no from dine_in_order where order_key=@OrderKey and Tiltid=@TiltId  SELECT @intErrorCode = @@ERROR     IF (@intErrorCode <> 0) GOTO PROBLEM  if @discount > 0 begin set @CurrDiscount=round(((@discount/@sub_total)*100),2) set @DiscountPercent= cast(@CurrDiscount as nvarchar(50))+'%' Declare @CareOf as nvarchar(50); Select @CareOf = CareOff from Dine_In_Order where order_key = @OrderKey  insert into discount (date,order_key,order_num,c_o,order_type,discount,[percent],z_num,order_price,Tiltid,CounterId) values (@date,@OrderKey,@Ordernumber,@CareOf,@order_type,@discount,@DiscountPercent,@z_number,@net_sale,@TiltId,@CounterId)  end select @AccStatus as 'AccStatus';  COMMIT TRAN PROBLEM: IF (@intErrorCode <> 0) BEGIN  set @AccStatus = 0; select @AccStatus as 'AccStatus';     ROLLBACK TRAN END execute dbo.uspGetErrorInfo